function numIslands(grid) {
  const rows = grid.length;
  if (rows === 0) return 0;
  const cols = grid[0].length;
  const visited = new Set();               // "row,col" strings
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  function flood(startRow, startCol) {
    const stack = [[startRow, startCol]];   // iterative DFS: no recursion depth limits
    visited.add(startRow + ',' + startCol);
    while (stack.length > 0) {
      const [row, col] = stack.pop();
      for (const [dRow, dCol] of directions) {
        const nextRow = row + dRow;
        const nextCol = col + dCol;
        const key = nextRow + ',' + nextCol;
        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
        if (grid[nextRow][nextCol] !== 1 || visited.has(key)) continue;
        visited.add(key);
        stack.push([nextRow, nextCol]);
      }
    }
  }

  let islands = 0;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      if (grid[row][col] === 1 && !visited.has(row + ',' + col)) {
        islands += 1;
        flood(row, col);
      }
    }
  }
  return islands;
}

